#[cfg(feature = "prices")]
#[doc = "Create a price"]
pub async fn create_price(
    client: &crate::Client,
    params: &crate::prices::CreatePriceParams,
) -> Result<crate::prices::Price, crate::Error> {
    let path = crate::params::format_path("/v1/prices", &[]);
    client.post_form(&path, params).await
}

#[cfg(feature = "prices")]
#[doc = "Retrieve a price"]
pub async fn get_price(
    client: &crate::Client,
    price: &str,
    params: &crate::prices::GetPriceParams,
) -> Result<crate::prices::Price, crate::Error> {
    let path = crate::params::format_path("/v1/prices/{price}", &[("price", price)]);
    client.get(&path, params).await
}

